head.b:skin:
/* Atlas theme: base styles. Component CSS is added by later tasks.
   Theme Designer colours:
   <Variable name="bg" description="Background" type="color" default="#f7f5f1" value="#f7f5f1"/>
   <Variable name="ink" description="Text" type="color" default="#151716" value="#151716"/>
   <Variable name="accent" description="Accent" type="color" default="#1f5f4a" value="#1f5f4a"/>
   <Variable name="accent2" description="Accent 2" type="color" default="#c8a96a" value="#c8a96a"/>
*/
:root{
  --bg:$(bg); --surface:#fff; --ink:$(ink); --muted:#6b6f6c; --line:#e6e2da;
  --accent:$(accent); --accent-2:$(accent2); --accent-soft:#e3ece8;
  --radius:16px; --wrap:1200px; --ease:cubic-bezier(.2,.7,.2,1);
}
*{box-sizing:border-box;margin:0}
html{scroll-behavior:smooth}
body{font-family:"IBM Plex Sans Arabic",system-ui,sans-serif;background:var(--bg);color:var(--ink);line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;cursor:pointer}
/* theme icons default size; owner content in .post-body keeps its own (zero specificity) */
:where(svg:not(.post-body svg)){width:20px;height:20px;flex:none}
[hidden]{display:none!important}
html[dir=rtl] .flip{transform:scaleX(-1)}

/* bilingual: one span per language, the html lang decides */
html[lang=fr] [lang=ar], html[lang=ar] [lang=fr]{display:none}

.wrap{max-width:var(--wrap);margin:auto;padding:0 16px}

.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:50px;padding:0 22px;border-radius:999px;font-weight:600;font-size:15px;border:1px solid transparent;transition:transform .3s var(--ease),background .3s}
.btn:hover{transform:translateY(-2px)}
.btn svg{transition:transform .3s var(--ease)}
.btn:hover svg.flip{transform:translateX(4px)}
html[dir=rtl] .btn:hover svg.flip{transform:scaleX(-1) translateX(4px)}
.btn-primary{background:var(--accent);color:#fff}
.btn-light{background:#fff;color:var(--ink)}
.btn-ghost{border-color:var(--line);background:var(--surface)}
.btn-glass{border-color:rgba(255,255,255,.35);color:#fff;background:rgba(255,255,255,.08);backdrop-filter:blur(6px)}

/* reveal on scroll */
.rv{transition:opacity .8s var(--ease),transform .8s var(--ease);transition-delay:var(--d,0s)}
.js .rv{opacity:0;transform:translateY(28px)}
.js .rv.in{opacity:1;transform:none}

/* header: solid by default; transparent over the hero only on the home page with JS (init() adds .solid after scrolling).
   Header1 and LinkList2 sit in the bar */
#top{position:fixed;inset:0 0 auto;z-index:30;background-color:rgba(247,245,241,.9);backdrop-filter:blur(12px);color:var(--ink);box-shadow:0 1px 0 var(--line);transition:background-color .4s,color .4s,box-shadow .4s}
.js .home #top:not(.solid){background-color:transparent;backdrop-filter:none;color:#fff;box-shadow:0 1px 0 transparent}
.bar{display:flex;align-items:center;gap:28px;height:72px}
.bar #header,.bar .widget{display:contents}
.logo{display:flex;align-items:center;gap:12px}
.logo .mark{width:40px;height:40px;border-radius:12px;background:var(--accent);color:#fff;display:grid;place-items:center;box-shadow:inset 0 0 0 1px rgba(255,255,255,.12)}
.logo .mark svg{width:24px;height:24px}
.logo img{height:40px;width:auto}
.logo .name{display:grid;line-height:1.15}
.logo .name b{font-size:18px;font-weight:700;letter-spacing:.01em}
.logo .name small{font-size:11px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;opacity:.7}
html[lang=ar] .logo .name small{letter-spacing:0;font-size:12px}
/* views without a hero: the bar is always solid and the content starts below it */
.inner #main{padding-top:72px}
.bar nav{display:flex;gap:26px;margin-inline-start:auto;font-size:14px}
.bar nav a{opacity:.8;position:relative;padding:4px 0}
.bar nav a::after{content:"";position:absolute;inset:auto 0 0;height:1.5px;background:currentColor;transform:scaleX(0);transition:transform .35s var(--ease)}
.bar nav a:hover{opacity:1}
.bar nav a:hover::after{transform:scaleX(1)}
/* language switch: segmented pill, the thumb slides to the active language */
.lang{position:relative;display:flex;align-items:center;height:40px;padding:3px;border-radius:999px;background:var(--surface);border:1px solid var(--line);backdrop-filter:blur(8px);direction:ltr}
.js .home #top:not(.solid) .lang{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.25)}
.lang .globe{width:16px;height:16px;margin:0 6px 0 8px;opacity:.75}
.lang button{position:relative;z-index:1;height:32px;min-width:40px;padding:0 10px;border:0;border-radius:999px;background:none;font-size:13px;font-weight:600;opacity:.75;transition:color .35s,opacity .35s}
.lang button[aria-pressed=true]{opacity:1;color:#fff}
.lang .thumb{position:absolute;top:3px;bottom:3px;border-radius:999px;background:var(--accent);box-shadow:0 2px 8px rgba(0,0,0,.15);transition:left .35s var(--ease),width .35s var(--ease)}
.js .home #top:not(.solid) .lang .thumb{background:#fff}
.js .home #top:not(.solid) .lang button[aria-pressed=true]{color:var(--ink)}
.bar .btn{height:42px;font-size:14px}

/* home-only sections: their widgets render nothing elsewhere, the boxes go too */
.inner #hero,.inner #marquee,.inner #services,.inner #beforeafter,.inner .blk{display:none}

/* hero slider: Image2 is slide 1 + the text, Image3 and Image4 are image-only slides; init() adds the dots */
.hero{position:relative;height:100svh;min-height:600px;color:#fff;overflow:hidden;padding:0}
.slide{position:absolute;inset:0;opacity:0;transition:opacity 1.2s ease}
.slide.on{opacity:1}
.slide img{width:100%;height:100%;object-fit:cover;transform:scale(1.12)}
.slide.on img{animation:kb 8s linear forwards}
@keyframes kb{to{transform:scale(1)}}
.hero::after{content:"";position:absolute;inset:0;background:linear-gradient(to top,rgba(10,12,11,.92),rgba(10,12,11,.45) 45%,rgba(10,12,11,.1) 75%,rgba(10,12,11,.4))}
.hero-in{position:absolute;inset:auto 0 0;z-index:2;padding-bottom:56px}
.hero h1{font-size:clamp(38px,7vw,84px);line-height:1.04;font-weight:700;letter-spacing:-.02em;max-width:900px}
html[lang=ar] .hero h1{line-height:1.25;letter-spacing:0}
.line{display:block;overflow:hidden}
.line>span{display:block;animation:up 1s var(--ease) both;animation-delay:var(--d)}
@keyframes up{from{transform:translateY(105%)}}
.hero p{font-size:18px;opacity:.85;margin:18px 0 30px;animation:fade 1s .5s both}
.hero .cta{display:flex;flex-wrap:wrap;gap:12px;animation:fade 1s .7s both}
@keyframes fade{from{opacity:0;transform:translateY(14px)}}
.hero-foot{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-top:48px;padding-top:24px;border-top:1px solid rgba(255,255,255,.2)}
.dots{display:flex;gap:8px}
/* 27px tall hit area, only the 3px content box is painted */
.dots{margin:-12px 0}
.dots button{width:36px;height:27px;border:0;background:rgba(255,255,255,.3) content-box;padding:12px 0;position:relative;overflow:hidden}
.dots button.on::after{content:"";position:absolute;inset:12px 0;background:#fff;transform-origin:left;animation:bar 6s linear forwards}
html[dir=rtl] .dots button.on::after{transform-origin:right}
.hero:hover .dots .on::after,.hero:focus-within .dots .on::after{animation-play-state:paused}
@keyframes bar{from{transform:scaleX(0)}}
.counter{font-size:14px;opacity:.8;font-variant-numeric:tabular-nums;direction:ltr}
@media (max-width:560px){
  .hero .cta{flex-direction:column}
  .hero-foot .counter{display:none}
}

/* marquee: LinkList3 names, rendered once, copied by init() */
.marquee{background:var(--ink);color:#fff;overflow:hidden;padding:22px 0;direction:ltr}
.mq-track{display:flex;width:max-content;animation:mq 30s linear infinite}
.marquee:hover .mq-track{animation-play-state:paused}
html[dir=rtl] .mq-track{animation-direction:reverse}
.mq-track>span{display:flex;align-items:center;gap:28px;padding-inline-end:28px;font-size:clamp(20px,3vw,30px);font-weight:600;white-space:nowrap}
.mq-track>span::after{content:"";width:10px;height:10px;border-radius:50%;background:var(--accent-2)}
@keyframes mq{to{transform:translateX(-50%)}}

/* services bento: Image5 = heading + big tile, HTML1 = small tiles (init() adds the icon) */
.bento{display:grid;grid-template-columns:repeat(4,1fr);grid-template-rows:auto;grid-auto-rows:220px;gap:16px;padding:96px 0}
.bento .widget{display:contents}
.bento .hd{grid-column:1/-1}
.bento h2{margin-bottom:24px}
.tile{position:relative;border-radius:var(--radius);background:var(--surface);border:1px solid var(--line);padding:26px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;transition:opacity .8s var(--ease) var(--d,0s),transform .5s var(--ease),box-shadow .5s}
.tile:hover,.js .tile.in:hover{transform:translateY(-4px);box-shadow:0 20px 40px -20px rgba(0,0,0,.18)}
.tile>h3{margin-top:auto}
.tile .ico{width:48px;height:48px;border-radius:14px;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center}
.tile h3{font-size:18px;font-weight:600}
.tile p{font-size:14px;color:var(--muted)}
.tile.big{grid-column:span 2;grid-row:span 2;color:#fff;border:0}
.tile.big img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform 1.2s var(--ease)}
.tile.big:hover img{transform:scale(1.06)}
.tile.big::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(to top,rgba(0,0,0,.7),transparent 60%)}
.tile.big>*:not(img){position:relative;z-index:2}
.tile.big .ico{background:rgba(255,255,255,.15);color:#fff;backdrop-filter:blur(6px)}
.tile.big h3{font-size:26px}
.tile.big p{color:rgba(255,255,255,.8)}
.tile.wide{grid-column:span 2;background:var(--accent);color:#fff;border:0}
.tile.wide .ico{background:rgba(255,255,255,.14);color:#fff}
.tile.wide p{color:rgba(255,255,255,.75)}
@media (max-width:960px){
  .bento{grid-template-columns:1fr 1fr;grid-auto-rows:190px}
}
@media (max-width:560px){
  .bento{grid-template-columns:1fr;grid-auto-rows:auto;padding:72px 0}
  .tile{min-height:150px;gap:24px}
  .tile>h3+p{margin-top:-24px}
  .tile.big,.tile.wide{grid-column:auto;grid-row:auto}
  .tile.big{min-height:320px}
}

/* before / after: LinkList4 = text column; Image6 and Image7 stack in one cell, Image7's range drives --pos */
.ba-wrap{display:grid;grid-template-columns:1fr 1.4fr;grid-template-areas:"t b";gap:56px;align-items:center;padding-bottom:96px}
.ba-wrap .LinkList{grid-area:t}
.ba-wrap .Image{grid-area:b}
.ba{position:relative;aspect-ratio:4/3;border-radius:20px;overflow:hidden;direction:ltr;--pos:50%;user-select:none}
.ba img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ba .before{filter:grayscale(1) contrast(.85) brightness(.85) sepia(.25)}
.ba .after{clip-path:inset(0 0 0 var(--pos))}
.ba .handle{position:absolute;z-index:1;top:0;bottom:0;left:var(--pos);width:2px;background:#fff;transform:translateX(-1px);pointer-events:none}
.ba .handle i{position:absolute;top:50%;left:50%;width:46px;height:46px;border-radius:50%;background:#fff;color:var(--ink);transform:translate(-50%,-50%);display:grid;place-items:center;box-shadow:0 6px 20px rgba(0,0,0,.25)}
.ba .tag{position:absolute;z-index:1;top:16px;padding:6px 12px;border-radius:999px;background:rgba(0,0,0,.55);color:#fff;font-size:12px;font-weight:600;backdrop-filter:blur(6px)}
.ba .tag.l{left:16px}.ba .tag.r{right:16px}
.ba input{position:absolute;z-index:2;inset:0;width:100%;height:100%;opacity:0;cursor:ew-resize;margin:0}
.steps{display:grid;gap:4px;margin-top:8px;counter-reset:s}
.step{display:flex;gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid var(--line);font-weight:600}
.step::before{counter-increment:s;content:"0" counter(s);font-size:13px;color:var(--accent);font-weight:700;min-width:24px}
@media (max-width:960px){
  .ba-wrap{grid-template-columns:1fr;grid-template-areas:"t" "b";gap:32px}
}
@media (max-width:560px){
  .ba-wrap{padding-bottom:72px}
}

/* projects: home carousel (Blog1), lists grid, post and static page, 404 */
.projs{padding-bottom:96px}
.head{display:flex;justify-content:space-between;align-items:end;gap:16px;flex-wrap:wrap;margin-bottom:32px}
.head h2{margin-bottom:0}
.arrows{display:flex;gap:8px}
.arrows button{width:50px;height:50px;border-radius:50%;border:1px solid var(--line);background:var(--surface);display:grid;place-items:center;transition:background .3s,color .3s}
.arrows button:hover{background:var(--ink);color:#fff}
.track{display:grid;grid-auto-flow:column;grid-auto-columns:min(78%,400px);gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none;padding-inline:max(16px,calc((100vw - var(--wrap))/2 + 16px));scroll-padding-inline:max(16px,calc((100vw - var(--wrap))/2 + 16px))}
.track::-webkit-scrollbar{display:none}
.proj{display:block;scroll-snap-align:start}
.proj .img{position:relative;border-radius:var(--radius);overflow:hidden;aspect-ratio:4/5;background:var(--accent-soft)}
.proj img{width:100%;height:100%;object-fit:cover;transition:transform 1s var(--ease)}
.proj:hover img{transform:scale(1.07)}
.ph{height:100%;display:grid;place-items:center;color:var(--accent)}
.ph svg{width:48px;height:48px;opacity:.5}
.proj .badge{position:absolute;top:14px;inset-inline-start:14px;padding:6px 12px;border-radius:999px;background:rgba(255,255,255,.9);font-size:12px;font-weight:600}
.proj h3{font-size:17px;font-weight:600;margin-top:14px}
.meta{font-size:13px;color:var(--muted)}
.list,.post,.nf{padding-top:56px;padding-bottom:96px}
.list h1,.post h1,.nf h1{font-size:clamp(32px,5vw,52px);line-height:1.1;font-weight:700;letter-spacing:-.02em;margin:10px 0 32px}
html[lang=ar] .list h1,html[lang=ar] .post h1,html[lang=ar] .nf h1{line-height:1.3;letter-spacing:0}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:32px 20px}
.empty{color:var(--muted)}
.post{max-width:860px}
/* project page: quiet back link above the title, facts strip below it */
.post .back{display:inline-flex;align-items:center;gap:6px;font-size:14px;color:var(--muted);transition:color .3s}
.post .back:hover{color:var(--ink)}
.post .back svg{width:16px;height:16px}
.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:16px;margin:-8px 0 32px;padding:18px 0;border-block:1px solid var(--line)}
.facts dt{font-size:12px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}
html[lang=ar] .facts dt{letter-spacing:0;font-size:13px}
.facts dd{margin:4px 0 0;font-size:16px;font-weight:600}
.facts a:hover{color:var(--accent)}
.facts .meta{font-size:inherit;color:inherit}
.post-body{font-size:17px;overflow-wrap:anywhere}
.post-body>*+*,.post-body div+div{margin-top:16px}
.post-body img{width:100%;height:auto;border-radius:var(--radius);margin-block:16px}
.post-body a:has(img){margin:0!important}
.post-body iframe{max-width:100%}
.post-foot{display:flex;flex-wrap:wrap;gap:12px;margin-top:40px;padding-top:32px;border-top:1px solid var(--line)}
.pager{display:flex;flex-wrap:wrap;gap:12px;margin-top:40px}
.pager .older{margin-inline-start:auto}

/* numbers, reviews, team: each in a .blk wrapper (home only); HTML2 / HTML3 / Image8-11 fill the sections */
.blk{margin-bottom:96px}
/* no figure, no review or no member: the whole block (heading, border, dark box) goes */
.blk:not(:has(.nums b,.review,.member)){display:none}
/* numbers: HTML2 = one <div><b data-count data-suffix>final value</b><span>label</span></div> per figure (the owner writes the final value); init() counts up when it enters view */
.nums{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;border-block:1px solid var(--line);padding:40px 0}
.nums .widget{display:contents}
.nums b{display:block;font-size:clamp(34px,5vw,56px);font-weight:700;line-height:1;letter-spacing:-.02em;font-variant-numeric:tabular-nums;direction:ltr}
html[dir=rtl] .nums b{text-align:right}
.nums span{font-size:14px;color:var(--muted)}
/* reviews: HTML3 = .review blocks in a scroll-snap track, init() adds the dots */
.reviews{background:var(--ink);color:#fff;border-radius:28px;padding:64px 0 40px;overflow:hidden}
.rtrack{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;scroll-behavior:smooth}
.rtrack::-webkit-scrollbar{display:none}
.review{flex:0 0 100%;scroll-snap-align:center;padding:0 clamp(24px,8vw,120px);text-align:center}
.stars{display:flex;gap:3px;justify-content:center;color:var(--accent-2);margin-bottom:24px}
.stars svg{width:18px;height:18px;fill:currentColor}
.review blockquote{font-size:clamp(22px,3vw,32px);line-height:1.4;font-weight:500;max-width:760px;margin:auto}
.who{display:inline-flex;align-items:center;gap:12px;margin-top:32px;text-align:start}
.who small{display:block;color:#a9ada9}
.rdots{display:flex;justify-content:center;gap:8px;margin-top:40px}
.rdots button{position:relative;width:8px;height:8px;border-radius:999px;border:0;padding:0;background:rgba(255,255,255,.3);transition:width .4s var(--ease),background .4s}
.rdots button::before{content:"";position:absolute;inset:-10px -4px}
.rdots button.on{width:28px;background:#fff}
/* team: Image8-11, TITLE = name, CAPTION = role (both "FR | AR"); greyscale until hovered */
.team{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.team .widget{display:contents}
.team .widget:nth-child(4n+2) .member{--d:.1s}.team .widget:nth-child(4n+3) .member{--d:.2s}.team .widget:nth-child(4n+4) .member{--d:.3s}
.member .img{border-radius:var(--radius);overflow:hidden;aspect-ratio:3/4}
.member img{width:100%;height:100%;object-fit:cover;filter:grayscale(1);transition:filter .6s,transform 1s var(--ease)}
.member:hover img{filter:none;transform:scale(1.04)}
.member h3{font-size:16px;font-weight:600;margin-top:12px}
.member .role{font-size:13px;color:var(--muted)}
@media (max-width:960px){
  .nums{grid-template-columns:1fr 1fr;row-gap:32px}
  .team{grid-template-columns:1fr 1fr}
}
@media (max-width:560px){
  .blk{margin-bottom:72px}
  .blk.rev{padding:0}
  .reviews{border-radius:20px;padding:48px 0 32px}
}

/* contact band: Image1 is the background, LinkList1 the content */
.contact-wrap{margin-bottom:24px}
.cta-band{position:relative;isolation:isolate;border-radius:28px;overflow:hidden;color:#fff;background:var(--accent)}
.cta-band::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(100deg,rgba(15,40,32,.95),rgba(15,40,32,.6))}
html[dir=rtl] .cta-band::before{background:linear-gradient(-100deg,rgba(15,40,32,.95),rgba(15,40,32,.6))}
.cta-band .Image{position:absolute;inset:0;z-index:-2}
.cta-band .Image img{width:100%;height:100%;object-fit:cover}
.cta-band .LinkList{padding:72px 48px;display:grid;grid-template-columns:1.2fr 1fr;gap:40px;align-items:center}
.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:600;color:var(--accent);letter-spacing:.04em}
.eyebrow::before{content:"";width:18px;height:2px;background:currentColor}
:where(h2:not(.post-body h2)){font-size:clamp(28px,4.4vw,44px);line-height:1.15;font-weight:700;margin:10px 0 40px;letter-spacing:-.01em}
html[lang=ar] :where(h2:not(.post-body h2)){line-height:1.35;letter-spacing:0}
.cta-band h2{margin:10px 0 16px}
.cta-band .eyebrow{color:var(--accent-2)}
.cta-band .rows{display:grid;gap:10px;margin-top:28px}
.cta-band .r{display:flex;align-items:center;gap:12px;font-size:15px;opacity:.9}
.ltr{direction:ltr;unicode-bidi:isolate}
#wa-form{background:var(--surface);color:var(--ink);border-radius:20px;padding:24px;display:grid;gap:12px}
#wa-form input,#wa-form textarea{font:inherit;font-size:15px;border:1px solid var(--line);border-radius:12px;padding:13px 14px;background:var(--bg);color:var(--ink);width:100%;transition:border-color .3s,background .3s}
#wa-form input:focus,#wa-form textarea:focus{outline:0;border-color:var(--accent);background:#fff}
#wa-form textarea{min-height:100px;resize:vertical}

footer{padding:40px 0;font-size:13px;color:var(--muted)}
footer .wrap{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}

/* floating WhatsApp, mobile only */
.fab{position:fixed;bottom:16px;inset-inline-end:16px;width:58px;height:58px;border-radius:50%;background:var(--accent);color:#fff;display:none;place-items:center;box-shadow:0 10px 30px rgba(0,0,0,.25);z-index:40}
.fab::before{content:"";position:absolute;inset:0;border-radius:50%;background:var(--accent);animation:ping 2.4s ease-out infinite;z-index:-1}
@keyframes ping{to{transform:scale(1.6);opacity:0}}
.fab svg{width:26px;height:26px}
@media (max-width:960px){
  .bar nav,.bar .btn{display:none}
  .lang{margin-inline-start:auto}
  .cta-band .LinkList{grid-template-columns:1fr;padding:48px 24px}
  .fab{display:grid}
  footer{padding-bottom:96px}
}

@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
  .js .rv{opacity:1;transform:none}
  html,.track,.rtrack{scroll-behavior:auto}
}

body.script:
//
/* owner text "FR | AR": split on the first " | ", no bar = same text twice */
function splitBi(s){
  var i = s.indexOf(' | ');
  return i < 0 ? {fr: s.trim(), ar: s.trim()} : {fr: s.slice(0, i).trim(), ar: s.slice(i + 3).trim()};
}
/* WhatsApp link with a prefilled message; any other base is returned as is */
function waUrl(base, lines){
  if (!/wa\.me|api\.whatsapp\.com/.test(base)) return base;
  return base + (base.indexOf('?') < 0 ? '?' : '&') + 'text=' + encodeURIComponent(lines.join('\n'));
}
/* LocalBusiness keys only for the contact rows that exist; FR half of "FR | AR" */
function buildLd(base, items){
  var ld = Object.assign({}, base);
  if (items.phone) ld.telephone = splitBi(items.phone).fr;
  if (items.address) ld.address = {'@type': 'PostalAddress', streetAddress: splitBi(items.address).fr, addressCountry: 'MA'};
  return ld;
}
/* replace an element's text with one span per language */
function bi(el, text){
  var b = splitBi(text);
  el.textContent = '';
  ['fr', 'ar'].forEach(function(l){
    var s = document.createElement('span');
    s.lang = l; s.textContent = b[l]; el.appendChild(s);
  });
}
/* "FR | AR" text inside every .bi under root becomes one span per language; no bar = left alone */
function applyBi(root){
  [].slice.call((root || document).querySelectorAll('.bi:not([data-done])')).forEach(function(el){
    el.setAttribute('data-done', '');
    if (el.textContent.indexOf(' | ') > -1) bi(el, el.textContent);
  });
}
/* switch language: html lang/dir, placeholders (range: aria-label), pressed button + sliding thumb; keep = remember the choice */
function setLang(l, keep){
  var h = document.documentElement, t = document.querySelector('#lang .thumb');
  h.lang = l; h.dir = l == 'ar' ? 'rtl' : 'ltr';
  if (keep) try { localStorage['atlas-lang'] = l; } catch (e) {}
  [].forEach.call(document.querySelectorAll('[data-ar]'), function(el){ var v = el.getAttribute('data-' + l); if (el.type == 'range') el.setAttribute('aria-label', v); else el.placeholder = v; });
  [].forEach.call(document.querySelectorAll('#lang button'), function(b){
    var on = b.getAttribute('data-lang') == l;
    b.setAttribute('aria-pressed', on);
    if (on && t) { t.style.left = b.offsetLeft + 'px'; t.style.width = b.offsetWidth + 'px'; }
  });
}
/* slider step, wraps both ways */
function nextIndex(i, n, step){ return (i + step + n) % n; }
/* carousel scrollLeft runs negative under rtl */
function scrollSign(dir){ return dir == 'rtl' ? -1 : 1; }
function init(){
  var all = function(selector){ return [].slice.call(document.querySelectorAll(selector)); };
  var reducedMotion = matchMedia('(prefers-reduced-motion:reduce)').matches;

  /* reveal first, so a later failure can't leave content hidden; no IntersectionObserver = all shown */
  var observer = window.IntersectionObserver && new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if (entry.isIntersecting) { appear(entry.target); observer.unobserve(entry.target); }
    });
  }, {threshold: .15});
  /* count-up on reveal (ease-out cubic over 1.6s); final value at once with reduced motion or no observer */
  var countUp = function(el){
    var target = +el.getAttribute('data-count'), suffix = el.getAttribute('data-suffix') || '', start = performance.now();
    var tick = function(now){
      var progress = reducedMotion || !observer ? 1 : Math.min((now - start) / 1600, 1);
      el.textContent = Math.round(target * (1 - Math.pow(1 - progress, 3))) + suffix;
      if (progress < 1) requestAnimationFrame(tick);
    };
    tick(start);
  };
  var appear = function(el){ el.classList.add('in'); [].forEach.call(el.querySelectorAll('[data-count]'), countUp); };
  var reveal = function(el){ if (observer) observer.observe(el); else appear(el); };
  all('.rv').forEach(reveal);

  /* WhatsApp: the LinkList1 wa.me target goes on every [data-wa] link */
  var waSource = document.querySelector('[data-wa-src]'), wa = waSource ? waSource.getAttribute('data-wa-src') : '';
  if (wa) all('[data-wa]').forEach(function(a){ a.href = wa; a.target = '_blank'; a.rel = 'noopener'; });

  /* contact rows: collect phone/address/hours for the JSON-LD, then split "FR | AR" */
  var contactItems = {}, ldScript = document.getElementById('atlas-ld');
  all('[data-key]').forEach(function(el){
    var text = el.textContent.trim();
    contactItems[el.getAttribute('data-key')] = text;
    bi(el, text);
  });
  if (ldScript) try { ldScript.textContent = JSON.stringify(buildLd(JSON.parse(ldScript.textContent), contactItems)); } catch (e) {}
  applyBi();

  /* language switch */
  all('#lang button').forEach(function(b){ b.onclick = function(){ setLang(b.getAttribute('data-lang'), true); }; });
  /* place the thumb without the slide-in: transition off, reflow, transition back on */
  var placeThumb = function(){
    var thumb = document.querySelector('#lang .thumb');
    thumb.style.transition = 'none';
    setLang(document.documentElement.lang);
    void thumb.offsetWidth;
    thumb.style.transition = '';
  };
  placeThumb();
  if (document.fonts) document.fonts.ready.then(placeThumb);

  /* header turns solid once the hero is mostly scrolled past */
  var header = document.getElementById('top');
  var updateHeader = function(){ header.classList.toggle('solid', window.scrollY > window.innerHeight * .7); };
  addEventListener('scroll', updateHeader, {passive: true});
  updateHeader();

  /* footer: blog title "FR | AR" and the current year */
  all('[data-bi]').forEach(function(el){ bi(el, el.textContent.trim()); });
  all('[data-year]').forEach(function(el){ el.textContent = '© ' + new Date().getFullYear(); });

  /* contact form: shown only with a WhatsApp target, sends a prefilled message */
  var form = document.getElementById('wa-form');
  if (form && wa) {
    form.hidden = false;
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var field = function(name){ return form.elements[name].value.trim(); };
      window.open(waUrl(wa, ['Nom: ' + field('name'), 'Tel: ' + field('phone'), field('msg')]), '_blank', 'noopener');
    });
  }

  /* hero: dots for 2+ slides; the active dot's CSS bar animation ends = next slide (CSS pauses it on hover/focus) */
  var slides = all('.slide'), slideCount = slides.length, dots = all('.hero .dots')[0], current = 0;
  var showSlide = function(i){
    current = i;
    slides.forEach(function(slide, k){ slide.classList.toggle('on', k == i); });
    if (slideCount < 2 || !dots) return;
    /* reflow between removing and re-adding .on restarts the bar animation */
    [].forEach.call(dots.children, function(dot, k){ dot.className = ''; if (k == i) { void dot.offsetWidth; dot.className = 'on'; } });
    all('.hero .counter')[0].textContent = '0' + (i + 1) + ' / 0' + slideCount;
  };
  if (dots && slideCount > 1) {
    slides.forEach(function(slide, k){ dots.innerHTML += '<button type="button" aria-label="' + (k + 1) + '"></button>'; });
    dots.onclick = function(e){ var k = [].indexOf.call(dots.children, e.target); if (k > -1) showSlide(k); };
    dots.addEventListener('animationend', function(){ showSlide(nextIndex(current, slideCount, 1)); });
  }
  showSlide(0);

  /* marquee: four copies, the extra ones hidden from screen readers */
  all('.mq-track').forEach(function(track){
    var original = track.children.length, html = track.innerHTML;
    track.innerHTML += html + html + html;
    [].slice.call(track.children, original).forEach(function(copy){ copy.setAttribute('aria-hidden', 'true'); });
  });

  /* service tiles: icon from data-icon (unknown = home), staggered reveal */
  all('.tile[data-icon]').forEach(function(tile, k){
    var icon = tile.getAttribute('data-icon');
    if (!/^(paint|tile|drop|bolt|shield|clock|chat|home)$/.test(icon)) icon = 'home';
    tile.insertAdjacentHTML('afterbegin', '<div class="ico"><svg><use href="#i-' + icon + '"/></svg></div>');
    tile.className += ' rv';
    reveal(tile);
    tile.style.setProperty('--d', k % 2 ? '.16s' : '.08s');
  });

  /* numbers: each figure reveals in turn (the count-up runs in appear) */
  all('.nums [data-count]').forEach(function(figure, k){
    var box = figure.parentNode;
    box.className += ' rv';
    box.style.setProperty('--d', k * .1 + 's');
    reveal(box);
  });

  /* reviews: dots follow the scroll; autoplay waits while hovered, focused or touched in the last 8s */
  var reviewTrack = all('.rtrack')[0], reviewCount = reviewTrack ? reviewTrack.children.length : 0;
  var reviewBox = reviewTrack && reviewTrack.closest('.reviews'), touchedAt = 0;
  if (reviewCount > 1) {
    var currentReview = function(){ return Math.round(Math.abs(reviewTrack.scrollLeft) / reviewTrack.offsetWidth); };
    var goToReview = function(i){ reviewTrack.scrollTo({left: reviewTrack.offsetWidth * i * scrollSign(document.documentElement.dir)}); };
    reviewTrack.insertAdjacentHTML('afterend', '<div class="rdots">' + [].map.call(reviewTrack.children, function(c, k){ return '<button type="button" aria-label="' + (k + 1) + '"></button>'; }).join('') + '</div>');
    var reviewDots = reviewTrack.nextSibling;
    var markDot = function(){ var i = currentReview(); [].forEach.call(reviewDots.children, function(dot, k){ dot.className = k == i ? 'on' : ''; }); };
    reviewDots.onclick = function(e){ var k = [].indexOf.call(reviewDots.children, e.target); if (k > -1) goToReview(k); };
    reviewTrack.addEventListener('scroll', markDot, {passive: true});
    reviewBox.onpointerdown = function(){ touchedAt = Date.now(); };
    markDot();
    if (!reducedMotion) setInterval(function(){
      var hovered = matchMedia('(hover:hover)').matches && reviewBox.matches(':hover');
      var focused = reviewBox.contains(document.activeElement);
      if (!hovered && !focused && Date.now() - touchedAt > 8e3) goToReview(nextIndex(currentReview(), reviewCount, 1));
    }, 5e3);
  }

  /* before / after: the range sets --pos on Image7's box */
  var range = all('.ba input')[0];
  if (range) range.oninput = function(){ range.parentNode.style.setProperty('--pos', range.value + '%'); };

  /* projects carousel: one card (+ 20px gap) per click, mirrored under rtl */
  all('.arrows button').forEach(function(b){
    b.onclick = function(){
      var track = all('.track')[0];
      track.scrollBy({left: (track.firstElementChild.offsetWidth + 20) * b.getAttribute('data-dir') * scrollSign(document.documentElement.dir)});
    };
  });
  /* project cards show the year only */
  all('time.meta').forEach(function(time){ var year = (time.getAttribute('datetime') || '').slice(0, 4); if (year) time.textContent = year; });
}
if (typeof document !== 'undefined') init();
if (typeof module !== 'undefined') module.exports = {splitBi: splitBi, waUrl: waUrl, buildLd: buildLd, setLang: setLang, applyBi: applyBi, nextIndex: nextIndex, scrollSign: scrollSign};
//
